contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // Before opening, donate must revert for any amount
        bool revertedBefore;
        c.donate{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedBefore = true; } else { revertedBefore = false; }
        // Owner opens the contract to the public
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        // After opening, donate with the same amount
        uint balBefore = address(c).balance;
        bool revertedAfter;
        c.donate{value: amount}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedAfter = true; } else { revertedAfter = false; }
        uint balAfter = address(c).balance;
        assert(revertedBefore && (revertedAfter || balAfter == balBefore));
    }
}

