contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        bool revertedBefore;
        try c.donate{value: amount}() { revertedBefore = false; } catch { revertedBefore = true; }
        try c.OpenToThePublic() {} catch { return; }
        uint balBefore = address(c).balance;
        bool revertedAfter;
        try c.donate{value: amount}() { revertedAfter = false; } catch { revertedAfter = true; }
        uint balAfter = address(c).balance;
        assertTrue(revertedBefore && (revertedAfter || balAfter == balBefore));
